"""Compare independent numerical-policy evidence without treating similarity as truth."""
import json,sys
from pathlib import Path
import numpy as np
R=Path(__file__).resolve().parent;sys.path.insert(0,str(R.parents[3]/'skills/precision-compare/scripts'))
from array_compare import compare_arrays
from score_metrics import reduce_scores

def run(mode):
 dirs={s:R/(s+'-'+mode+'-evidence/artifacts') for s in ['gpu','npu']};read=lambda p:json.loads(p.read_text())
 result=dict(mode=mode,classification='numerical-policy evaluation; no upstream correctness violation inferred from peer similarity',results={s:read(p/'result.json') for s,p in dirs.items()})
 if mode=='rmsnorm-operator':
  op={s:read(p/'operator.json') for s,p in dirs.items()}
  for k in ['input','weight','cotangent','epsilon']:assert op['gpu'][k]==op['npu'][k],k
  for s in op:assert op[s]['values']['native']['historical_fullhash_exact']
  result['operator']=op;result['hash_equal']={name:{k:op['gpu']['values'][name][k]['sha256']==op['npu']['values'][name][k]['sha256'] for k in ['output','input_vjp']} for name in ['native','candidate']};result['candidate_fp32_hash_equal']={k:op['gpu']['values']['candidate']['fp32_boundary'][k]['sha256']==op['npu']['values']['candidate']['fp32_boundary'][k]['sha256'] for k in ['output','input_vjp','weight_vjp']}
 else:
  cfg={s:read(p/'configuration.json') for s,p in dirs.items()}
  for k in ['ids','mask','positions','labels','trainable','model_parameters','layers']:assert cfg['gpu'][k]==cfg['npu'][k],k
  expected=list(cfg['gpu']['trainable']);assert len(expected)==80
  result['config_matched']=True
  for name in ['initial','gradients','updates']:
   arrays={}
   for s,p in dirs.items():
    with np.load(p/(name+'.npz')) as z:arrays[s]={k:z[k] for k in z.files}
    assert set(arrays[s])==set(expected)
   comp=compare_arrays(arrays['gpu'],arrays['npu'],expected=expected,metrics=True);result[name]=comp
   if name=='initial':assert comp['exact_equal']
   else:comp['opposite_sign_coordinates']=int(sum(np.count_nonzero((arrays['gpu'][k]>0)&(arrays['npu'][k]<0)|(arrays['gpu'][k]<0)&(arrays['npu'][k]>0)) for k in expected))
   if name in ['gradients','updates']:
    key='base_model.model.model.language_model.layers.7.self_attn.v_proj.lora_B.default.weight';result.setdefault('target_coordinate',{})[name]={s:float(arrays[s][key][302,1]) for s in dirs}
  targets={s:{(v['position'],v['token']):v['logprob'] for v in read(p/'targets.json')} for s,p in dirs.items()};assert len(targets['gpu'])==len(targets['npu'])==123;result['targets']=reduce_scores(targets['gpu'],targets['npu']);result['baseline']=read(Path(read(R/'resources.json')['baseline_comparison']))
 target=R/(mode+'-comparison.json');assert not target.exists();target.write_text(json.dumps(result,indent=2)+'\n');print(json.dumps(result if mode=='rmsnorm-operator' else {k:result[k] for k in ['mode','results','targets','target_coordinate']},indent=2));return result
if __name__=='__main__':run(sys.argv[1])
